const ViewDesigner = (props) => {
    const {
        designersRequest,
        // error,
        // requesting,
        // designersFailure,
        deleteDesignersRequest
    } = props;

    const handleOnClick = (id) => {
        window.confirm("Are you sure you want to delete this designer")
        deleteDesignersRequest(id)
    }

    const { designers } = props

    useEffect(() => {
        designersRequest()
    }, [])

    const columns = [
        {
            title: 'Name',
            dataIndex: 'name',
            key: 'name',
            render: (text, image) =>
                <div>
                    {image.photo ? <img className='profile-image' src={image.photo} alt="profile-image" /> : <div className='no-image'></div>}
                    <a onClick={() => history.push('/admin/profile')}>{text}</a>
                </div>
        },
        {
            title: 'Email',
            dataIndex: 'email',
            key: 'email',
        },
        {
            title: 'Phone Number',
            dataIndex: 'phone_number',
            key: 'phone_number',
        },
        {
            title: 'Action',
            key: 'action',
            render: (item, record) => (
                <Space size="middle">
                    <Button onClick={() => { handleOnClick(record.id); console.log(record.id) }} title='Remove' className='action-btn' />
                </Space>
            ),
        },
    ];

    return (
        <HomeLayout>
            <div className='table-wrapper'>
                <span className='table-heading'>Community Designer List</span>
                <div className='table-section'>
                    <ListTable columns={columns} data={designers} />
                </div>
            </div>
        </HomeLayout>
    )
}

const mapStateToProps = (state) => ({
    designers: state.designers.designers,
    error: state.designers.error,
    requesting: state.designers.requesting,
});

const mapDispatchToProps = (dispatch) => ({
    designersRequest: () => dispatch(designersRequest()),
    designersFailure: () => dispatch(designersFailure()),
    deleteDesignersRequest: (data) => dispatch(deleteDesignersRequest(data)),
    deleteDesignersFailure: (data) => dispatch(deleteDesignersFailure(data)),
});

// export default ManageServices;
export default connect(mapStateToProps, mapDispatchToProps)(ViewDesigner);
