import {
  POST_SERVICE_REQUEST,
  POST_SERVICE_SUCCESS,
  POST_SERVICE_FAILURE,
} from "./type"

const initialState = {
  servicesInfo: false,
  error: false,
  requesting: false,
}

export default (state = initialState, action) => {
  switch (action.type) {
    case POST_SERVICE_REQUEST:
      return {
        ...state,
        requesting: true
      }

    case POST_SERVICE_SUCCESS:
      return {
        ...state,
        requesting: false,
        servicesInfo: action.data
      }
    case POST_SERVICE_FAILURE:
      return {
        ...state,
        requesting: false,
        error: action.data
      }

    default:
      return state
  }
}
