import {
  GET_RESIDENTS_REQUEST,
  GET_RESIDENTS_SUCCESS,
  GET_RESIDENTS_FAILURE,
} from "./type"

const initialState = {
  residents: false,
  error: false,
  requesting: false,
}

export default (state = initialState, action) => {
  switch (action.type) {
    case GET_RESIDENTS_REQUEST:
      return {
        ...state,
        requesting: true
      }

    case GET_RESIDENTS_SUCCESS:
      return {
        ...state,
        requesting: false,
        residents: action.data
      }
    case GET_RESIDENTS_FAILURE:
      return {
        ...state,
        requesting: false,
        error: action.data
      }

    default:
      return state
  }
}
