import {
  POST_LOGIN_REQUEST,
  POST_LOGIN_SUCCESS,
  POST_LOGIN_FAILURE,
  LOGOUT
} from "./type"

const initialState = {
  loginInfo: false,
  error: false,
  requesting: false,
  accessToken: false,
}

export default (state = initialState, action) => {
  switch (action.type) {
    case POST_LOGIN_REQUEST:
      return {
        ...state,
        requesting: true
      }

    case POST_LOGIN_SUCCESS:
      return {
        ...state,
        requesting: false,
        loginInfo: action.data
      }
    case POST_LOGIN_FAILURE:
      return {
        ...state,
        requesting: false,
        error: action.data
      }
    case LOGOUT:
      return {
        ...state,
        requesting: false,
      }

    default:
      return state
  }
}
