import React, { useEffect } from 'react'

// Components
import HomeLayout from '../../layout/HomeLayout'
import UInput from '../../components/UInput';
import Button from '../../components/Button';

// Style
import './style.scss'

// Icons
import servicesArrow from '../../assets/images/servicesArrow.svg'

// Routing
import { history } from '../../reduxStore/store';

// Redux
import {
    postServiceRequest,
    postServiceFailure,
} from './redux/action'

import useForm from '../../utils/useForm';
import { connect } from 'react-redux';


const CreateService = (props) => {
    const {
        postServiceRequest,
        BEError,
        requesting,
        postServiceFailure,
    } = props;

    useEffect(() => {
        postServiceFailure(false)
    }, [])


    const stateSchema = {
        name: {
            value: '',
            error: '',
        },
        price: {
            value: '',
            error: '',
        },
    };

    const validationStateSchema = {
        name: {
            required: true,
        },
        price: {
            required: true,
        },
    };

    const { state, handleOnChange, setState } = useForm(
        stateSchema,
        validationStateSchema,
    );

    const onSubmit = () => {
        const data = {
            name: state.name.value,
            price: state.price.value,
        };
        postServiceRequest(data);
    };

    return (
        <HomeLayout>
            <div className='create-service-wrapper'>
                <div className='create-service-heading-wrapper'>
                    <img onClick={() => history.goBack()} className='create-service-arrow' src={servicesArrow} alt='arrow' />
                    <span className='create-service-heading'>Create Service</span>
                </div>
                <div className='create-service-input-fields'>
                    <UInput
                        placeholder="Service Name"
                        type='text'
                        className='create-service-name'
                        value={state.name.value}
                        onChange={(val) =>
                            handleOnChange('name', val.target.value)
                        }
                        onFocus={() => {
                            postServiceFailure(false);
                        }}
                        inputError={BEError?.name}
                        errorText={BEError?.name || state.name.error}
                        errorClass={
                            BEError?.name || state.name.error ? 'opacity-1' : ''
                        }

                    />
                    <UInput
                        type='text'
                        placeholder='Price'
                        className='create-service-price'
                        value={state.price.value}
                        onChange={(val) =>
                            handleOnChange('price', val.target.value)
                        }
                        onFocus={() => {
                            postServiceFailure(false);
                        }}
                        inputError={BEError?.price}
                        errorText={BEError?.price || state.price.error}
                        errorClass={
                            BEError?.price || state.price.error ? 'opacity-1' : ''
                        }

                    />
                </div>
                <Button
                    title="Add"
                    className="create-service-button"
                    onClick={() => onSubmit()}
                    showSpinner={requesting}
                />
            </div>
        </HomeLayout>
    )
}

const mapStateToProps = (state) => ({
    servicesInfo: state.services.services,
    BEError: state.postServices.error,
    requesting: state.services.requesting,
});

const mapDispatchToProps = (dispatch) => ({
    postServiceRequest: (data) => dispatch(postServiceRequest(data)),
    postServiceFailure: (data) => dispatch(postServiceFailure(data)),
});

export default connect(mapStateToProps, mapDispatchToProps)(CreateService);
