import {
  GET_BOOKINGS_REQUEST,
  GET_BOOKINGS_SUCCESS,
  GET_BOOKINGS_FAILURE,
} from "./type"

const initialState = {
  bookings: false,
  error: false,
  requesting: false,
}

export default (state = initialState, action) => {
  switch (action.type) {
    case GET_BOOKINGS_REQUEST:
      return {
        ...state,
        requesting: true
      }

    case GET_BOOKINGS_SUCCESS:
      return {
        ...state,
        requesting: false,
        bookings: action.data
      }
    case GET_BOOKINGS_FAILURE:
      return {
        ...state,
        requesting: false,
        error: action.data
      }

    default:
      return state
  }
}
